#include <algorithm>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll w, m, k;
    cin >> w >> m >> k;

    ll budget = w / k;
    ll len = 0;

    int digits = 1;
    i128 nextPower = 10;
    while (nextPower <= m) {
        nextPower *= 10;
        ++digits;
    }

    i128 current = m;

    while (budget > 0) {
        i128 available = nextPower - current;
        ll affordable = budget / digits;
        i128 take = min<i128>(available, affordable);

        len += static_cast<ll>(take);
        budget -= static_cast<ll>(take) * digits;

        if (take < available)
            break;

        current = nextPower;
        nextPower *= 10;
        ++digits;
    }

    cout << len;
    return 0;
}

