    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll w, m, k;
    cin >> w >> m >> k;

    i128 budget = w / k;
    i128 current = m;
    i128 power = 10;
    i128 digits = 1;
    i128 length = 0;

    while (power <= current) {
        power *= 10;
        ++digits;
    }

    while (true) {
        i128 count = power - current;
        i128 cost = count * digits;

        if (cost <= budget) {
            budget -= cost;
            length += count;
            current = power;
            power *= 10;
            ++digits;
        } else {
            length += budget / digits;
            break;
        }
    }

    cout << static_cast<ll>(length);
    return 0;
}

